import csv
import io
import json
import sys


def convert_csv(payload):
    """Convert CSV to string-valued records, or return invalid_input."""
    invalid = {"error": "invalid_input"}
    if not isinstance(payload, dict) or set(payload) != {"text", "delimiter"}:
        return invalid
    text = payload["text"]
    delimiter = payload["delimiter"]
    if not isinstance(text, str) or len(text) > 100000:
        return invalid
    if not isinstance(delimiter, str) or delimiter not in (",", ";", "\t"):
        return invalid

    try:
        reader = csv.reader(
            io.StringIO(text, newline=""),
            delimiter=delimiter,
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=True,
        )
        headers = next(reader, None)
        if not headers or len(set(headers)) != len(headers):
            return invalid
        records = []
        for row in reader:
            if len(row) != len(headers):
                return invalid
            records.append(dict(zip(headers, row)))
        return {"records": records}
    except (csv.Error, ValueError):
        return invalid


def main():
    try:
        payload = json.loads(sys.stdin.buffer.read().decode("utf-8"))
    except (UnicodeError, ValueError):
        result = {"error": "invalid_input"}
    else:
        result = convert_csv(payload)
    sys.stdout.write(json.dumps(result, ensure_ascii=True) + "\n")


if __name__ == "__main__":
    main()
